def check_primes(limit):
    results = {}
    for p in range(2, limit):
        if is_prime(p):
            found = False
            # The period is at most p-1, or slightly more if p is small.
            # For p > 3, the period of 6^n, 2^n, 3^n mod p is at most p-1.
            # Let's just check up to p*p or something safe.
            # Actually, the period is a divisor of p-1.
            # So checking up to p-1 should be enough.
            for n in range(1, p + 1):
                a_n = (pow(6, n, p) + pow(2, n, p) + pow(3, n, p) - 1) % p
                if a_n == 0:
                    found = True
                    results[p] = n
                    break
            if not found:
                results[p] = None
    return results

